  ('6bc843cf-7455-5042-b17a-0f13c7753fcb', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'bbf9b7d0-0ff3-5ffa-ac7d-61bc3f848741', 1, 'Modern agricultural communities are organized and implemented in joint...', 'សហគមន៍កសិកម្មទំនើបត្រូវបានរៀបចំ និងអនុវត្តផលិតកម្មរួមគ្នាដើម្បីបញ្ចុះថ្លៃ...', 'count', 'count_to_target', 'increase', 'if(${ind_011_value} != '''', round((${ind_011_value} div 8) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('44fbaf2f-b28b-574d-8d8b-344c69b2aa5b', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '78c1c45a-ffe6-52cf-82f6-20704294437b', 1, 'Number of cashew producer groups', 'ចំនួនបណ្តុំអ្នកផលិត ស្វាយចន្ទី', 'count', 'count_to_target', 'increase', 'if(${ind_012_value} != '''', round((${ind_012_value} div 5) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('b09141aa-22f7-5e05-ae4e-f67a262a0e8c', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '3d9ffb40-e9da-55c0-a7d5-34d7bb686609', 1, 'Coordinate for registering cashew nut associations or federations', 'សម្របសម្រួលការចុះបញ្ជីសមាគមឬសហព័ន្ធស្វាយចន្ទី', 'count', 'count_to_target', 'increase', 'if(${ind_013_value} != '''', round((${ind_013_value} div 3) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('403cf16c-5610-5adf-a61e-92a2f9eb43d1', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'e62b9f5e-c5c1-53f2-901c-ca770df9e183', 1, 'Contract farming in cashew production implemented', 'កសិកម្មតាមកិច្ចសន្យាក្នុងផលិតកម្មស្វាយចន្ទីត្រូវបានអនុវត្ត', 'count', 'count_to_target', 'increase', 'if(${ind_014_value} != '''', round((${ind_014_value} div 50) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('626267a7-cd4e-535b-975e-ba4c5fd4d9f2', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'daffa1d5-fad6-5697-bfa4-6bdb28f646d3', 1, 'Promote the registration of “Cambodian Cashew” internationally: - Prepare to register “Cambodian Cashew” as a collective brand or geographical indication of goods', 'ជំរុញការចុះបញ្ជី “ស្វាយ ចន្ទីកម្ពុជា” ជាលក្ខណៈអន្តរជាតិ:រៀបចំចុះបញ្ជី “ស្វាយចន្ទីកម្ពុជា” ជាម៉ាក សមូហភាព ឬម៉ាកសម្គាល់ភូមិសាស្រ្តទំនិញ', '%', 'percent_complete', 'increase', 'if(${ind_015_value} != '''', if(${ind_015_value} > 100, 100, ${ind_015_value}), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('2b31ba70-b2f4-5dfb-93ff-47e661606d83', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '1c51ee83-8d5b-570c-b552-b9f0c1f83013', 1, 'Prepare and create a book, charter or collective regulation to manage the use of the “Cambodian Cashew” brand, which specifies the cultivation, harvesting, processing, packaging and quality control systems .', 'រៀបចំបង្កើតសៀវភៅ បន្ទុក ឬបទបញ្ជារួមគ្រប់គ្រងការប្រើប្រាស់ម៉ាក “ស្វាយចន្ទីកម្ពុជា” ដែលមានកំណត់អំពីវិធីសាស្រ្តដាំដុះ ប្រមូលផល កែច្នៃវេចខ្ចប់ និងប្រព័ន្ធត្រួតពិនិត្យគុណភាព', '%', 'percent_complete', 'increase', 'if(${ind_016_value} != '''', if(${ind_016_value} > 100, 100, ${ind_016_value}), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('101fa05c-007f-5f8a-a180-b9a1d917e897', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'f4e9b2b7-1ab6-555a-b0cb-a470182275d1', 1, 'Increase the capacity of cashew producers to properly implement technical measures (Number of training courses for plantation owners)', 'បង្កើនសមត្ថភាពអ្នកផលិតស្វាយចន្ទីឱ្យបានត្រឹមត្រូវតាមបច្ចេកទេស(ចំនួនវគ្គបណ្តុះបណ្តាលដល់ម្ចាស់ចម្ការ)', 'count', 'count_to_target', 'increase', 'if(${ind_017_value} != '''', round((${ind_017_value} div 10) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('162303b9-f2dd-5db8-a789-4fc055131e01', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'b84a070e-3244-5155-8045-9204bda6f030', 1, 'Farms certified with Good Agricultural Practices (CamGAP)', 'ចម្ការទទួលបានការបញ្ជាក់ពីការអនុវត្តកសិកម្មល្អ (CamGAP)', 'count', 'count_to_target', 'increase', 'if(${ind_018_value} != '''', round((${ind_018_value} div 15) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('1f92057c-a3a8-5109-8d2b-5f9ff0b07b66', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'f5fae0ac-afaa-5eac-a257-3675b07bc312', 1, 'Cashew area certified as organic.', 'ផ្ទៃដីស្វាយចន្ទីទទួលបានការបញ្ជាក់ពីការអនុវត្តកសិកម្មសរីរាង្គ', 'count', 'count_to_target', 'increase', 'if(${ind_019_value} != '''', round((${ind_019_value} div 400) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
