តុតាង ឬរបាយការណ៍នានាបើមាន", "required": false, "suffix": "_evidence", "type": "file"}, {"en": "Any challenge faced during reporting period? What solution?", "hint": "Optional. Use this to explain constraints, coordination issues, data gaps, or suggested solutions.", "km": "បញ្ហាប្រឈម និង ដំណោះស្រាយ", "required": false, "suffix": "_feedback", "type": "text"}], "respondentFields": [{"en": "Name of Respondent", "hint": "", "km": "ឈ្មោះអ្នកផ្តល់ចម្លើយ", "name": "respondent_name", "type": "text"}, {"en": "Phone Number", "hint": "Enter phone number of the focal person.", "km": "លេខទូរស័ព្ទ", "name": "phone_number", "type": "text"}, {"en": "Reporting Year", "hint": "", "km": "ឆ្នាំដែលផ្តល់របាយការណ៍", "name": "reporting_year", "type": "select_one reporting_year"}, {"en": "Which ministry/institution are you responding for?", "hint": "Only indicators assigned to the selected ministry/institution will appear. Admin can see all indicators.", "km": "តើអ្នករាយការណ៍សម្រាប់ក្រសួង ឬស្ថាប័នណាដែរ?", "name": "reporting_ministry", "type": "select_one ministry"}], "rows": 907, "sections": [{"indicators": ["Indicator_001", "Indicator_002", "Indicator_003", "Indicator_004", "Indicator_005", "Indicator_006", "Indicator_007", "Indicator_010", "Indicator_011", "Indicator_014", "Indicator_017", "Indicator_018", "Indicator_019", "Indicator_062", "Indicator_103"], "label": "MAFF (Ministry of Agriculture, Forestry and Fisheries) indicator section (15 indicators)", "labelKm": "ផ្នែកសូចនាករ MAFF (ក្រសួងកសិកម្ម រុក្ខាប្រមាញ់ និងនេសាទ) (15 សូចនាករ)", "ministry": "maff", "name": "grp_maff", "relevant": "${reporting_ministry} = ''maff'' or ${reporting_ministry} = ''admin''"}, {"indicators": ["Indicator_008", "Indicator_009", "Indicator_041", "Indicator_042"], "label": "MoE (Ministry of Environment) indicator section (4 indicators)", "labelKm": "ផ្នែកសូចនាករ MoE (ក្រសួងបរិស្ថាន) (4 សូចនាករ)", "ministry": "moe", "name": "grp_moe", "relevant": "${reporting_ministry} = ''moe'' or ${reporting_ministry} = ''