insert into questions (id, workspace_id, form_version_id, field_name, indicator_id, purpose, type, label_en, label_km, hint_en, required, constraint_rule, sort_order) values
  ('e86fc1aa-a813-5d19-9d70-f9523e3c46a7', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '7cce73f8-326a-5272-b117-b364aae4128d', 'respondent_name', null, 'respondent', 'text', 'Name of Respondent', 'ឈ្មោះអ្នកផ្តល់ចម្លើយ', null, true, null, 1),
